    C('scythes-emperor','Косы Императора','Scythes of the Emperor','ultramarines','Третье Основание','Сота / флот','Терсиус','Оборона, борьба с Тиранидами',['#d2b531','#111111'],'Наследники Ультрамаринов, почти уничтоженные флотом-ульем Кракен и позднее восстановленные благодаря Примарис.',['Орден был связан с миром Сота и наследием Фароса.','Вторжение Кракена стало катастрофой, уничтожившей значительную часть ордена и его инфраструктуры.','Позднее Косы Императора были восстановлены в новой форме с использованием Примарис.'],['Сота','Флот-улей Кракен','Примарис','Выживание'],[['legion','ultramarines','XIII легион'],['location','sotha','Сота'],['event','iyanden-kraken','Война с Кракеном']]),
    C('doom-eagles','Орлы Рока','Doom Eagles','ultramarines','Неизвестное Основание','Гатан','неизвестно','Десантные операции, фаталистическая культура',['#777777','#b5242c'],'Наследники Ультрамаринов, для которых принятие неизбежности смерти является частью боевой философии.',['Орлы Рока считают каждого воина уже обречённым и стремятся встретить смерть достойно.','Такая культура делает их исключительно стойкими в операциях с высокими ожидаемыми потерями.'],['Фатализм','Десант','Ультрамаринская генолиния'],[['legion','ultramarines','XIII легион']]),
    C('aurora-chapter','Аврора','Aurora Chapter','ultramarines','Второе Основание','Фортресс-монастырь на мире Аврора','неизвестно','Танковая и механизированная война',['#2f743e','#e5e5e5'],'Наследники Ультрамаринов, известные большим количеством бронетехники и любовью к масштабным механизированным наступлениям.',['Аврора относится к ранним наследникам XIII легиона.','Орден поддерживает мощные бронетанковые силы и часто ведёт кампании с большим количеством Land Raider и других машин.'],['Бронетехника','Механизированная война','Второе Основание'],[['legion','ultramarines','XIII легион']]),
    C('brazen-claws','Медные Когти','Brazen Claws','iron-hands','Второе Основание','Флотский / бывший Медуза-подобный мир','неизвестно','Механизированная война',['#a93b28','#2e5f86'],'Наследники Железных Рук, сохранившие уважение к аугметике и тяжёлой технике, но развившие собственную культуру.',['Медные Когти были созданы во Второе Основание из X легиона.','В разных эпохах орден переживал тяжёлые потери и вынужденные перемещения.'],['Аугметика','Второе Основание','Железная генолиния'],[['legion','iron-hands','X легион']]),
    C('red-talons','Красные Когти','Red Talons','iron-hands','Второе Основание','Раум','неизвестно','Тотальная война, тяжёлая техника',['#a92327','#111111'],'Жестокий и прямолинейный наследник Железных Рук, основанный ветеранами, известными беспощадностью ещё во времена Ереси.',['Красные Когти происходят от клана Моррагула X легиона.','Их традиции подчёркивают уничтожение врага без сантиментов и широкое использование тяжёлого вооружения.'],['Моррагул','Тяжёлая техника','Второе Основание'],[['legion','iron-hands','X легион']]),
    C('sons-medusa','Сыны Медузы','Sons of Medusa','iron-hands','Признаны после Моирейского раскола','Флотский','неизвестно','Техно-мистицизм, механизированная война',['#4a913d','#e8e8e8'],'Орден, возникший из религиозно-технологического раскола внутри генетической линии Железных Рук.',['Сыны Медузы сформировались из сторонников Моирейского учения, изгнанных или отделившихся от других орденов.','Позднее их структура была официально признана Империумом как самостоятельный орден.'],['Моирейский раскол','Аугметика','Флотский орден'],[['legion','iron-hands','X легион']]),
    C('raptors','Рапторы','Raptors','raven-guard','Второе Основание','Неизвестно / мобильный','Луфус','Камуфляж, разведка, рациональная тактика',['#607045','#222222'],'Наследники Гвардии Ворона, известные прагматичной современной тактикой, камуфляжем и отсутствием показной героики.',['Рапторы происходят от XIX легиона и развили его традиции скрытности в максимально практичную доктрину.','Они охотно используют разведку, дальний огонь и маскировку, предпочитая результат ритуальной «красоте» боя.'],['Камуфляж','Разведка','Снайперы','Прагматизм'],[['legion','raven-guard','XIX легион']]),
    C('death-spectres','Призраки Смерти','Death Spectres','raven-guard','XIII Основание','Окклудус','Мегир','Защита Гул-Звёзд, ударные операции',['#111111','#e8e8e8'],'Мрачный орден на границе Гул-Звёзд, поддерживающий опасный сторожевой пост против угроз дальнего космоса.',['Призраки Смерти считаются наследниками Гвардии Ворона.','Их крепость и ритуалы тесно связаны с загадочным устройством Шариякс и постоянной угрозой со стороны Гул-Звёзд.'],['Гул-Звёзды','Окклудус','Тёмные ритуалы'],[['legion','raven-guard','XIX легион'],['location','ghoul-stars','Гул-Звёзды']]),
    C('revilers','Ревилеры','Revilers','raven-guard','Второе Основание','Неизвестно','неизвестно','Скрытность, внезапные удары',['#303030','#d5d5d5'],'Ранний орден-наследник Гвардии Ворона, сохранивший скрытную и диверсионную доктрину XIX легиона.',['Ревилеры происходят от ветеранов XIX легиона и считаются одним из древнейших наследников Коракса.','Они специализируются на разрушении командования и снабжения противника до генерального боя.'],['Скрытность','Второе Основание','Диверсии'],[['legion','raven-guard','XIX легион']]),
    C('angels-absolution','Ангелы Искупления','Angels of Absolution','dark-angels','Второе Основание','Флотский','неизвестно','Универсальная война, охота на Падших',['#d9d0b8','#234b44'],'Один из Непрощённых орденов, считающий, что его собственная вина за падение Калибана уже искуплена, но продолжающий охоту на Падших ради всей генолинии.',['Орден был создан во Второе Основание из I легиона.','Отношение Ангелов Искупления к древней вине отличается от большинства Непрощённых, однако секретность и общая миссия остаются.'],['Непрощённые','Второе Основание','Падшие'],[['legion','dark-angels','I легион'],['character','lion','Лион Эль’Джонсон']]),
    C('angels-redemption','Ангелы Возмездия','Angels of Redemption','dark-angels','Второе Основание','Флотский','неизвестно','Универсальная война',['#f1e5c7','#1f6a52'],'Наследники Тёмных Ангелов и часть Непрощённых, объединённых тайной Калибана и поиском Падших.',['Ангелы Возмездия происходят от I легиона.','Они поддерживают структуру внутреннего круга и общую сеть секретов Непрощённых.'],['Непрощённые','Падшие','Внутренний круг'],[['legion','dark-angels','I легион']]),
    C('consecrators','Консекраторы','Consecrators','dark-angels','Неизвестное раннее Основание','Флотский','Накерон','Реликвии, охота на утраченные артефакты',['#111111','#d3b75b'],'Наследник Тёмных Ангелов, известный использованием древней брони и реликвий времён легионов.',['Консекраторы входят в круг Непрощённых.','Многие их комплекты доспехов и оружия выглядят как музей эпохи Великого крестового похода, но применяются в реальном бою.'],['Древние реликвии','Непрощённые','Археотехнологии'],[['legion','dark-angels','I легион']]),
    C('disciples-caliban','Ученики Калибана','Disciples of Caliban','dark-angels','Позднее Основание','Флотский','неизвестно','Охота на Падших',['#111111','#54785d'],'Орден Непрощённых, созданный с особенно явной целью охоты на одного из наиболее опасных Падших.',['Ученики Калибана сохраняют структуру секретных кругов, типичную для наследников I легиона.','Их миссия тесно связана с древними преступлениями и тенями Калибана.'],['Непрощённые','Охота на Падших','Калибан'],[['legion','dark-angels','I легион'],['location','caliban','Калибан']]),
    C('storm-lords','Повелители Бури','Storm Lords','white-scars','Второе Основание','Неизвестно','неизвестно','Быстрые атаки, байки',['#d5d5d5','#c42428'],'Наследники Белых Шрамов, перенёсшие культуру скорости и мобильности V легиона в собственную яркую традицию.',['Повелители Бури относятся к ранним наследникам Белых Шрамов.','Орден известен широким использованием байков и стремительных ударов.'],['Байки','Скорость','Второе Основание'],[['legion','white-scars','V легион']]),
    C('mantis-warriors','Богомолы Воины','Mantis Warriors','white-scars','Неизвестное Основание','Одоната','Сартак','Засады, джунгли, разведка',['#4a8c35','#f0c52f'],'Орден-наследник Белых Шрамов, известный участием на стороне сецессионистов в Бадабской войне и последующим искупительным крестовым походом.',['Богомолы Воины долго защищали пограничные области от ксеносов и пиратов.','В Бадабской войне они поддержали Астральных Когтей, после чего были наказаны столетним крестовым походом.'],['Бадабская война','Засады','Искупительный крестовый поход'],[['legion','white-scars','V легион'],['event','badab-war','Бадабская война']]),
    C('covenant-fire','Ковенант Огня','Covenant of Fire','salamanders','Основание Ультима','Неизвестно','неизвестно','Огонь, поиск знаний',['#e5a633','#111111'],'Примарис-орден генолинии Саламандр, сочетающий прометеевские мотивы с поиском и уничтожением опасного знания.',['Ковенант Огня был создан в Основание Ультима из геносемени Вулкана.','Его братья проявляют особый интерес к древним текстам и реликвиям, оценивая их полезность или угрозу.'],['Основание Ультима','Прометеев культ','Поиск знаний'],[['legion','salamanders','XVIII легион']]),
    C('dark-krakens','Тёмные Кракены','Dark Krakens','salamanders','Основание Ультима','Нактрис','Мезоники Рейо','Охота на чудовищ, ночные операции',['#5c3e79','#111111'],'Примарис-орден Саламандр с водного мира Нактрис, превративший охоту на гигантских морских существ в часть воинской культуры.',['Тёмные Кракены происходят от геносемени Вулкана.','Их культура сформирована Нактрисом — миром чёрных океанов и опасной фауны.'],['Основание Ультима','Охота','Нактрис'],[['legion','salamanders','XVIII легион']]),
    C('black-dragons','Чёрные Драконы','Black Dragons','salamanders','Проклятое Основание (XXI, предполагаемая линия)','Неизвестно','неизвестно','Штурм, мутации костей',['#111111','#cfcfcf'],'Знаменитый орден Проклятого Основания, часть воинов которого обладает выраженными костяными мутациями и использует их в ближнем бою.',['Происхождение Чёрных Драконов традиционно связывают с генолинией Саламандр, но записи не абсолютно однозначны.','Костяные наросты некоторых братьев вызывают постоянное внимание Инквизиции.'],['Проклятое Основание','Мутации','Ближний бой'],[['legion','salamanders','XVIII легион']]),
    C('wolfspear','Волчье Копьё','Wolfspear','space-wolves','Основание Ультима','Флотский / Гарм','Ирик Стянольф','Охота, рейды, Примарис',['#747d85','#d8c69f'],'Примарис-наследник Космических Волков, созданный в эпоху Индомитус и развивающий фенрисийскую традицию вне самого Фенриса.',['Волчье Копьё было сформировано из Серых Щитов во время Основания Ультима.','Орден сохраняет генетическое наследие Русса, но формирует собственные саги и традиции.'],['Основание Ультима','Примарис','Генолиния Русса'],[['legion','space-wolves','VI легион'],['event','indomitus','Крестовый поход Индомитус']]),
    C('blood-ravens','Кровавые Вороны','Blood Ravens',null,'Неизвестное Основание','Омнис Арканум / флот','Габриэль Ангелос','Псайкеры, поиск реликвий, адаптивная тактика',['#8b1e23','#e2d6b0'],'Загадочный орден с неизвестным происхождением, прославившийся большим числом библиариев и событиями серии Dawn of War.',['Записи о происхождении Кровавых Воронов утрачены или намеренно скрыты.','Орден придаёт исключительное значение знаниям, реликвиям и поиску собственной истории.','Кампании в секторе Аурелия и Тартарусе сделали его одним из самых узнаваемых игровых орденов 40K.'],['Неизвестное происхождение','Библиарии','Реликвии','Dawn of War'],[['character','gabriel-angelos','Габриэль Ангелос'],['organization','blood-ravens','Кровавые Вороны']]),
    C('carcharodons','Кархародоны','Carcharodons', 'raven-guard','Неизвестное; происхождение спорно','Флотский / Оотека','Тайберос Красный Прилив','Штурм, ближний бой, рейды из пустоты',['#464b4c','#111111'],'Крайне древний и изолированный орден, известный безжалостными «Красными десятинами» и внезапными нападениями из пустоты.',['Происхождение Кархародонов намеренно туманно; часто упоминается возможная связь с генолинией Гвардии Ворона.','Орден большую часть времени действует далеко за пределами обычных имперских маршрутов.','Бадабская война сделала их методы широко известными другим имперским силам.'],['Флотский орден','Красная десятина','Бадабская война','Спорное происхождение'],[['character','tyberos','Тайберос'],['organization','carcharodons','Кархародоны'],['event','badab-war','Бадабская война']]),
    C('minotaurs','Минотавры','Minotaurs',null,'Неизвестное Основание','Флотский','Астерион Молок','Массовый штурм, война с другими Астартес',['#9b6c2f','#b82925'],'Таинственный орден, часто действующий как тяжёлый кулак Высших Лордов Терры и известный развертыванием почти всей численности единой силой.',['Происхождение Минотавров скрыто, а их снабжение необычно щедрое.','Орден неоднократно участвовал в конфликтах против других Астартес и имперских мятежников.'],['Высшие Лорды','Полное развёртывание','Астерион Молок'],[['character','asterion-moloc','Астерион Молок'],['organization','minotaurs','Минотавры'],['organization','high-lords','Высшие Лорды Терры']]),
    C('red-scorpions','Красные Скорпионы','Red Scorpions',null,'Неизвестное Основание','Флотский / Сарум','Караб Каллн','Чистота геносемени, апотекарии',['#4e4f50','#e4c64f'],'Орден, одержимый генетической чистотой и строгостью доктрины, часто действующий независимо от союзников.',['Красные Скорпионы известны повышенной ролью Апотекариона и постоянным контролем геносемени.','Они участвовали в Бадабской войне на стороне лоялистов и получили тяжёлые потери.'],['Генетическая чистота','Апотекарии','Бадабская война'],[['character','carab-culln','Караб Каллн'],['event','badab-war','Бадабская война']]),
    C('exorcists','Экзорцисты','Exorcists','imperial-fists','XIII Основание','Базилика Малифик','неизвестно','Антидемоническая война',['#9f2426','#111111'],'Секретный орден, чья подготовка включает контролируемое демоническое одержание и изгнание ради повышения устойчивости к варпу.',['Экзорцисты относятся к XIII Основанию и долгое время были окружены дезинформацией о своём происхождении.','Современные источники связывают их генетическую линию с Имперскими Кулаками.','Методы подготовки делают орден особенно ценным против демонических угроз.'],['Демоническое изгнание','Ордо Маллеус','XIII Основание'],[['legion','imperial-fists','VII легион'],['organization','ordo-malleus','Ордо Маллеус']]),
    C('grey-knights-chapter','Серые Рыцари','Grey Knights',null,'Особое основание в конце Ереси','Титан','Калдор Драйго','Демоны, варп, элитные псайкеры',['#aab2b6','#c99c43'],'Секретный орден Астартес, целиком состоящий из псайкеров и посвящённый борьбе с демонами. Его происхождение связано с Малкадором и финалом Ереси.',['Серые Рыцари были созданы как скрытый инструмент против угроз Имматериума.','Каждый боевой брат проходит исключительную психическую и духовную подготовку.','Орден тесно связан с Ордо Маллеус, но сохраняет собственную автономию и секретность.'],['Титан','Псайкеры','Демоны','Ордо Маллеус'],[['character','kaldor-draigo','Калдор Драйго'],['location','titan','Титан'],['organization','ordo-malleus','Ордо Маллеус'],['faction','grey-knights','Серые Рыцари']]),
    C('deathwatch-formation','Караул Смерти','Deathwatch',null,'Древнее специализированное формирование','Крепости дозора','неизвестно','Антиксеносные Kill Teams',['#111111','#c7c7c7'],'Особая структура Адептус Астартес, в которую временно или постоянно направляются ветераны множества орденов для службы Ордо Ксенос.',['Караул Смерти не является обычным орденом с единой генолинией.','Kill Teams собирают специалистов из разных орденов и используют их взаимодополняющие традиции против ксеносских угроз.'],['Ордо Ксенос','Kill Team','Смешанная генолиния'],[['organization','ordo-xenos','Ордо Ксенос'],['faction','deathwatch','Deathwatch']]),
    C('legion-damned','Легион Проклятых','Legion of the Damned',null,'Неизвестно','Неизвестно','неизвестно','Таинственные сверхъестественные вмешательства',['#111111','#e2d2b7'],'Мистические огненные Астартес, появляющиеся на безнадёжных полях боя и исчезающие после перелома сражения.',['Происхождение Легиона Проклятых неизвестно; одна из старых гипотез связывает его с исчезнувшими Огненными Ястребами.','Они появляются без предупреждения, демонстрируют сверхъестественную стойкость и почти не взаимодействуют с союзниками.'],['Тайна','Огненные доспехи','Неизвестное происхождение'],[]),
    C('celestial-lions','Небесные Львы','Celestial Lions','imperial-fists','Неизвестное Основание','Элизиум IX','Дюбаку','Оборона, стойкость',['#bd8a29','#1e4b82'],'Наследники Имперских Кулаков, чья открытая критика Инквизиции привела к цепи подозрительных катастроф и почти полному уничтожению ордена.',['Небесные Львы возмутились действиями Инквизиции после одной из кампаний и попытались добиться разбирательства.','Во время Третьей войны за Армагеддон орден начал нести аномально точечные потери среди командного состава.','Позднее Чёрные Храмовники помогли сохранить уцелевшее ядро генолинии.'],['Конфликт с Инквизицией','Армагеддон','Имперские Кулаки'],[['legion','imperial-fists','VII легион'],['event','third-armageddon','Третья война за Армагеддон'],['chapter','black-templars','Чёрные Храмовники']]),
    C('astral-claws','Астральные Когти','Astral Claws',null,'Неизвестное Основание','Бадаб','Луфгт Хурон','Крупные автономные силы, оборона Маэлстрома',['#4f6575','#d6aa45'],'Орден, ставший ядром Бадабского восстания. После поражения уцелевшие Астральные Когти превратились в Красных Корсаров.',['Луфгт Хурон расширил автономию и военную мощь ордена во время защиты Маэлстрома.','Спор о ресурсах, десятинах и власти перерос в Бадабскую войну.','После падения Бадаба Хурон и выжившие стали Красными Корсарами.'],['Бадабская война','Луфгт Хурон','Красные Корсары'],[['character','huron','Хурон Чёрное Сердце'],['location','badab','Бадаб'],['event','badab-war','Бадабская война'],['organization','red-corsairs','Красные Корсары']]),
    C('marines-malevolent','Злобные Космодесантники','Marines Malevolent',null,'Неизвестное Основание','Флотский','неизвестно','Агрессивная война с минимальным учётом потерь союзников',['#d0b128','#111111'],'Орден с крайне плохой репутацией среди союзников из-за презрения к гражданским потерям и жёсткого прагматизма.',['Злобные Космодесантники рассматривают потери обычных людей как допустимую цену за выполнение задачи.','Их культура снабжения и отношений с другими имперскими силами часто приводит к конфликтам.'],['Безжалостность','Конфликты с союзниками','Флотский орден'],[]),
    C('tome-keepers','Хранители Фолиантов','Tome Keepers','ultramarines','Четвёртое Основание','Иакатон','неизвестно','Знание, кодексная война',['#efe5ca','#24282a'],'Наследники Ультрамаринов, для которых архивирование, история и анализ знаний являются центральной частью орденской культуры.',['Орден был создан в Четвёртое Основание из геносемени XIII легиона.','Хранители Фолиантов фиксируют опыт кампаний и превращают его в практическое тактическое знание.'],['Четвёртое Основание','Архивы','Codex Astartes'],[['legion','ultramarines','XIII легион']]),
    C('silver-templars','Серебряные Храмовники','Silver Templars','ultramarines','Основание Ультима','Новара','Акилиос Занарис','Дуэли, точная дисциплина',['#a4a9a9','#25559d'],'Примарис-орден генолинии Ультрамаринов, известный культом индивидуального мастерства оружия и ритуальными поединками.',['Серебряные Храмовники были сформированы в Основание Ультима.','Боевые братья уделяют исключительное внимание личному владению выбранным оружием.'],['Основание Ультима','Примарис','Дуэли'],[['legion','ultramarines','XIII легион']]),
    C('howling-griffons','Воющие Грифоны','Howling Griffons','ultramarines','Неизвестное Основание','Манчера','неизвестно','Строгое соблюдение клятв',['#c62828','#d7bb29'],'Наследники Ультрамаринов, известные сложной геральдикой и почти фанатичным отношением к данным клятвам.',['Воющие Грифоны следуют кодексной структуре и придают огромный вес обещаниям, данным перед кампанией.','Орден участвовал в многочисленных войнах Империума, включая Бадабскую.'],['Клятвы','Геральдика','Бадабская война'],[['legion','ultramarines','XIII легион'],['event','badab-war','Бадабская война']]),
    C('star-phantoms','Звёздные Фантомы','Star Phantoms',null,'Неизвестное Основание','Флотский','неизвестно','Тяжёлое вооружение, уничтожение укреплений',['#e1e1e1','#111111'],'Независимый и мрачный орден, известный тяжёлой огневой мощью и ключевой ролью в финале Бадабской войны.',['Происхождение Звёздных Фантомов остаётся спорным и официально не раскрыто.','Именно их силы нанесли решающий удар по Хурону в конце Бадабской войны.'],['Бадабская война','Тяжёлое оружие','Спорное происхождение'],[['event','badab-war','Бадабская война'],['character','huron','Хурон']]),
    C('mentors','Менторы','Mentors',null,'XXVI Основание','Флотский','неизвестно','Военные советники, экспериментальное снаряжение',['#e5e4da','#2b6b54'],'Орден, специализирующийся на работе малыми группами с другими имперскими армиями и испытании тактики и технологий.',['Менторы часто отправляют отдельных специалистов или небольшие подразделения к союзным силам.','Это позволяет им собирать боевые данные и распространять эффективные методы по Империуму.'],['Советники','Экспериментальная тактика','Малые группы'],[]),
    C('sons-phoenix','Сыны Феникса','Sons of the Phoenix','imperial-fists','Основание Ультима','Неизвестно','неизвестно','Крестовые походы, религиозный пыл',['#e6e1db','#6a3c75'],'Примарис-орден, официально происходящий от Имперских Кулаков и известный ярко выраженной религиозной культурой.',['Сыны Феникса созданы в Основание Ультима.','Их официальная генетическая линия относится к Рогалу Дорну; внешние сходства с иными легионами остаются лишь фанатскими теориями.'],['Основание Ультима','Имперские Кулаки','Религиозность'],[['legion','imperial-fists','VII легион']]),
    C('black-vipers','Чёрные Гадюки','Black Vipers','salamanders','Основание Ультима','Неизвестно','неизвестно','Примарис, штурм',['#111111','#4a8c47'],'Примарис-наследники Саламандр, о которых даже внутри Империума существует мало надёжных сведений.',['Чёрные Гадюки были созданы в Основание Ультима из геносемени Вулкана.','Их контакты с родительским орденом ограничены и окружены бюрократической тайной.'],['Основание Ультима','Саламандры','Малоизвестный орден'],[['legion','salamanders','XVIII легион']]),
    C('emperor-spears','Копья Императора','Emperor\'s Spears','ultramarines','XXV Основание','Неметон','Амиад','Агрессивная мобильная война',['#5e83a8','#e4e1d9'],'Наследники Ультрамаринов, защищающие регион Элара и известные культурой варварских кланов Неметона.',['Копья Императора относятся к более поздним наследникам XIII легиона.','После Великого Разлома их регион оказался в Imperium Nihilus, что сделало орден важной частью локальной обороны без надёжной связи с Террой.'],['Imperium Nihilus','Неметон','Элара'],[['legion','ultramarines','XIII легион'],['event','great-rift','Великий Разлом']])
